const b = $json.body || (typeof $json === 'object' && !('headers' in $json) ? $json : {});
// Vi normaliserer til et fast hendelsesdokument. Feltet 'body' kan ha alarmer
// (Alertmanager) eller være rådata fra andre kilder. Trekker ut det vi kan.
const map = (o) => typeof o === 'string' ? o : (o ? JSON.stringify(o) : '');
const out = {
  source: String(b.source || b.job || $json.source || 'ukjent'),
  type: String(b.type || b.alertname || b.status || (b.alerts && b.alerts[0] && b.alerts[0].labels && b.alerts[0].labels.alertname) || 'hendelse'),
  severity: String(b.severity || (b.alerts && b.alerts[0] && b.alerts[0].labels && b.alerts[0].labels.severity) || 'info'),
  title: String(b.title || (b.alerts && b.alerts[0] && b.alerts[0].annotations && b.alerts[0].annotations.summary) || ''),
  message: String(b.message || b.msg || (b.alerts && b.alerts[0] && b.alerts[0].annotations && b.alerts[0].annotations.description) || ''),
  host: String(b.host || b.instance || $json.host || ''),
  at: new Date().toISOString(),
  details: map(b)
};
return [{ json: out }];
